KG42.register("edges-726dc6029e266d0440e89aa2",{"id":"S-7cac7e7e05679c72","source":"COMP-b646a091517c6af0","type":"links","target":"COMP-443a9bf9853dcd78","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["15-multiagent_reverse_auction"],"assertions":[{"id":"15-multiagent_reverse_auction::v141-c-R004::E::v141-c-R004-E002","paper":"15-multiagent_reverse_auction","rule_id":"v141-c-R004","rule_ref":"15-multiagent_reverse_auction::v141-c-R004","record":{"edge_id":"v141-c-R004-E002","source":"coordination.local_operator","target":"clearing.local","type":"links","constraint_ids":["v141-c-R004-C002"],"evidence_ids":["v141-b-g01-E21"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R004-C002"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-b646a091517c6af0","target":"COMP-443a9bf9853dcd78","source_occurrence_id":"15-multiagent_reverse_auction::v141-c-R004::V::coordination.local_operator","target_occurrence_id":"15-multiagent_reverse_auction::v141-c-R004::V::clearing.local","source_unit_id":"15-multiagent_reverse_auction::v141-a-M01::coordination.local_operator","target_unit_id":"15-multiagent_reverse_auction::v141-a-M01::clearing.local","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Demand allocation among qualified bidders in the hour-ahead reverse auction. | Hour-ahead allocation of the grid-connected microgrid's lumped demand among qualified DER bidders. | Local DER procurement in the grid-connected microgrid's hour-ahead reverse auction under insufficient supply. | Procurement objective for the microgrid's lumped load in the hour-ahead reverse auction. | Residual demand allocation among qualified bidders in the hour-ahead reverse auction.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E19","v141-b-g01-E21"]},"active":true,"source_signature":"ccb410bc32ea143ddab37657eed47e8776575c7414ed58c3227f925531d40110","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"DER supply submissions declaring available power and the next-hour price are sent to and collected by the DER aggregator. Scope: Next-hour DER bids in the hour-ahead reverse auction for the grid-connected microgrid's lumped load. The aggregator's procurement objective is to purchase the required amount of energy with the least cost. Scope: Procurement for the lumped load through the hour-ahead reverse auction in the studied grid-connected microgrid.","target_definition":"The local allocation process uses the qualified bidder's submitted supply to check whether that bidder can cover all demand. Scope: Hour-ahead allocation of the grid-connected microgrid's lumped demand among qualified DER bidders. The aggregator coordinates local procurement by buying the qualified amount of power from DERs, with the remaining demand purchased from the utility. Scope: Local DER procurement in the grid-connected microgrid's hour-ahead reverse auction under insufficient supply. Condition: Total supply is less than demand and some bidders participate in the auction. Local procurement aims to purchase the required amount of power at the lowest cost. Scope: Procurement objective for the microgrid's lumped load in the hour-ahead reverse auction. The first qualified bidder is supposed to cover the majority of the total demand. Scope: Demand allocation among qualified bidders in the hour-ahead reverse auction. The second qualifying bidder covers the remaining demand. Scope: Residual demand allocation among qualified bidders in the hour-ahead reverse auction. Condition: A supply deficit remains after the first qualified bidder's contribution.","constraints":[{"constraint_id":"v141-c-R004-C002","kind":"procedural","role":"core","statement":"The aggregator coordinates local procurement by buying the qualified amount of power from DERs, with the remaining demand purchased from the utility. Scope: Local DER procurement in the grid-connected microgrid's hour-ahead reverse auction under insufficient supply. Condition: Total supply is less than demand and some bidders participate in the auction.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E21"]}],"evidence":[{"evidence_id":"v141-b-g01-E21","location":{"location_id":"src-1b3df4bc99-p05-c1r3__v141-a-M01-validation","page":5,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"to check whether qualiﬁed bidder’s submission is able to cover all demand. The ﬁrst qualiﬁed bidder ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"exception"},"source_text":"If all base prices of the generation units in the microgrid are higher than the utility base price and none of them are interested in participating in the auction, the aggregator agent buys all required power from the utility. If the total supply is less than the demand and some of the bidders are participating in the auction, the aggregator agent buys qualified amount of power from the DERs and the remaining is purchased from the utility."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Demand allocation among qualified bidders in the hour-ahead reverse auction. | Hour-ahead allocation of the grid-connected microgrid's lumped demand among qualified DER bidders. | Local DER procurement in the grid-connected microgrid's hour-ahead reverse auction under insufficient supply. | Procurement objective for the microgrid's lumped load in the hour-ahead reverse auction. | Residual demand allocation among qualified bidders in the hour-ahead reverse auction.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E19","v141-b-g01-E21"]},"source_record":{"edge_id":"v141-c-R004-E002","source":"coordination.local_operator","target":"clearing.local","type":"links","constraint_ids":["v141-c-R004-C002"],"evidence_ids":["v141-b-g01-E21"]},"paper_scope_note":"Registration, auction invitation, bid, eligibility, and final power command are checked separately; the utility base price differs from the DER private base price; the general single-winner and two-winner cases are not combined into the same condition."}}],"assertion_ids":["15-multiagent_reverse_auction::v141-c-R004::E::v141-c-R004-E002"]});
